export const createCallbackRoutes = () => {
    const routes = new Map();
    const finished = new Map();
    const set = (id, deliver) => {
        routes.set(id, deliver);
    };
    const remove = (id) => {
        if (!routes.delete(id))
            return false;
        finished.set(id, 'cancelled');
        return true;
    };
    const deliver = (id, response) => {
        const fn = routes.get(id);
        if (!fn) {
            return finished.get(id) ?? 'unknown';
        }
        routes.delete(id);
        finished.set(id, 'delivered');
        fn(response);
        return 'ok';
    };
    const fail = (error) => {
        for (const [id] of routes.entries()) {
            deliver(id, { ok: false, error });
        }
    };
    return {
        set,
        remove,
        deliver,
        fail,
    };
};
